// DeleteEach deletes each selected active model through normal lifecycle behavior. Soft-delete models remain stored; other models are physically removed. The positive limit bounds the complete atomic candidate set before hooks run.
func (q RecordQuery) DeleteEach(ctx context.Context, writer database.Transactor, limit int) ([]Record, error) {
	return q.Query.RemoveEach(ctx, writer, limit)
}

// FirstOrCreate returns the first primary-ordered matching model or creates one through its normal lifecycle. The draft is prepared only when no model matches; the stored creation must satisfy the query. Internal lookup skips Retrieved. Concurrent absence relies on database unique constraints and reports ordinary conflicts without hidden retries.
func (q RecordQuery) FirstOrCreate(ctx context.Context, writer database.Transactor, create RecordDraft) (Record, error) {
	return q.Query.FirstOrInsert(ctx, writer, create)
}

// UpdateOrCreate runs a concrete draft callback for the first primary-ordered matching model or creates from the separate creation draft. Only the chosen branch prepares its draft; ordinary lifecycle and transaction ownership remain in force. Read ordering, pagination and eager-loading options are rejected.
func (q RecordQuery) UpdateOrCreate(ctx context.Context, writer database.Transactor, create RecordDraft, draft func(context.Context, *database.Tx, Record) (RecordDraft, error)) (Record, error) {
	var callback func(context.Context, *database.Tx, Record) (foundryquery.Mutation[Record], error)
	if draft != nil {
		callback = func(ctx context.Context, tx *database.Tx, current Record) (foundryquery.Mutation[Record], error) {
			d, err := draft(ctx, tx, current)
			if err != nil {
				return foundryquery.Mutation[Record]{}, err
			}
			return d.foundryMutation(false)
		}
	}
	return q.Query.PatchOrInsert(ctx, writer, create, callback)
}

