// FoundryCreateMutation supplies the typed draft adapter for framework integrations. Defaults fill omitted fields before UUID preparation; no mutators or database calls run here.
func (d RecordDraft) FoundryCreateMutation(defaults foundryquery.Mutation[Record]) (foundryquery.Mutation[Record], error) {
	values, err := foundryquery.ReadCreateDefaults((Record{}).FoundryQuery(), defaults)
	if err != nil {
		return foundryquery.Mutation[Record]{}, err
	}
	if !d.fieldID.IsSet() {
		v, err := foundryquery.MutationValue[Record, int](values, "binary_records", "id")
		if err != nil {
			return foundryquery.Mutation[Record]{}, err
		}
		d.fieldID = v
	}
	if !d.fieldBody.IsSet() {
		v, err := foundryquery.MutationValue[Record, Input](values, "binary_records", "body")
		if err != nil {
			return foundryquery.Mutation[Record]{}, err
		}
		d.fieldBody = v
	}
	if !d.fieldRaw.IsSet() {
		v, err := foundryquery.MutationValue[Record, []byte](values, "binary_records", "raw")
		if err != nil {
			return foundryquery.Mutation[Record]{}, err
		}
		d.fieldRaw = v
	}
	if !d.fieldNote.IsSet() {
		v, err := foundryquery.MutationValue[Record, foundryvalue.Nullable[Input]](values, "binary_records", "note")
		if err != nil {
			return foundryquery.Mutation[Record]{}, err
		}
		d.fieldNote = v
	}
	if !d.fieldEncoded.IsSet() {
		v, err := foundryquery.MutationValue[Record, Input](values, "binary_records", "encoded")
		if err != nil {
			return foundryquery.Mutation[Record]{}, err
		}
		d.fieldEncoded = v
	}
	return d.foundryMutation(true)
}
func (d RecordDraft) foundryMutation(create bool) (foundryquery.Mutation[Record], error) {
	var assignments []foundryquery.Assignment[Record]
	if v, set := d.fieldID.Get(); set {
		assignments = append(assignments, foundryquery.Assign[Record]("binary_records", "id", codec.Signed[int](), v))
	}
	if v, set := d.fieldBody.Get(); set {
		assignments = append(assignments, foundryquery.AssignClonedInput[Record]("binary_records", "body", codec.Bytes[Input](), v))
	}
	if v, set := d.fieldRaw.Get(); set {
		assignments = append(assignments, foundryquery.Assign[Record]("binary_records", "raw", codec.Bytes[[]byte](), v))
	}
	if v, set := d.fieldNote.Get(); set {
		assignments = append(assignments, foundryquery.AssignClonedInput[Record]("binary_records", "note", codec.Nullable(codec.Bytes[Input]()), v))
	}
	if v, set := d.fieldEncoded.Get(); set {
		assignments = append(assignments, foundryquery.AssignClonedInput[Record]("binary_records", "encoded", codec.Bytes[Input](), v))
	}
	return foundryquery.Change(assignments...), nil
}

// RecordDraft tracks explicitly selected mutation fields, preserving omitted, zero and null states.
type RecordDraft struct {
	fieldID      foundryvalue.Optional[int]
	fieldBody    foundryvalue.Optional[Input]
	fieldRaw     foundryvalue.Optional[[]byte]
	fieldNote    foundryvalue.Optional[foundryvalue.Nullable[Input]]
	fieldEncoded foundryvalue.Optional[Input]
}

// ID returns the typed mutation state for id.
func (d RecordDraft) ID() foundryvalue.Optional[int] { return d.fieldID }

// SetID returns a new draft with id explicitly set.
func (d RecordDraft) SetID(v int) RecordDraft { d.fieldID = foundryvalue.Set(v); return d }

// UnsetID omits id without requesting a zero or null write.
func (d RecordDraft) UnsetID() RecordDraft { d.fieldID = foundryvalue.Optional[int]{}; return d }

// Body returns the typed mutation state for body.
// Binary persistence uses bytea and owns byte buffers in drafts, query values and change snapshots. A non-nil empty slice is present; nil is invalid. Use Nullable and the generated Clear setter for SQL NULL. Binary fields cannot be identity or relation keys.
// Record.Body retains stored binary_records.body. Custom setter: [Record.MutateBody] transforms assigned values during persistence through [RecordDraft.SetBody]. Direct field assignment and draft construction do not invoke it.
// The custom setter accepts binarymodels.Input and produces stored binarymodels.Payload; pass fresh input to the draft/conflict setter and use stored values for query comparisons.
func (d RecordDraft) Body() foundryvalue.Optional[Input] {
	return codec.Bytes[Input]().CloneOptional(d.fieldBody)
}

// SetBody returns a new draft with body explicitly set.
// Binary persistence uses bytea and owns byte buffers in drafts, query values and change snapshots. A non-nil empty slice is present; nil is invalid. Use Nullable and the generated Clear setter for SQL NULL. Binary fields cannot be identity or relation keys.
// Record.Body retains stored binary_records.body. Custom setter: [Record.MutateBody] transforms assigned values during persistence through [RecordDraft.SetBody]. Direct field assignment and draft construction do not invoke it.
// The custom setter accepts binarymodels.Input and produces stored binarymodels.Payload; pass fresh input to the draft/conflict setter and use stored values for query comparisons.
func (d RecordDraft) SetBody(v Input) RecordDraft {
	d.fieldBody = foundryvalue.Set(codec.Bytes[Input]().Clone(v))
	return d
}

// UnsetBody omits body without requesting a zero or null write.
func (d RecordDraft) UnsetBody() RecordDraft { d.fieldBody = foundryvalue.Optional[Input]{}; return d }

// Raw returns the typed mutation state for raw.
// Binary persistence uses bytea and owns byte buffers in drafts, query values and change snapshots. A non-nil empty slice is present; nil is invalid. Use Nullable and the generated Clear setter for SQL NULL. Binary fields cannot be identity or relation keys.
