// IsEmpty reports whether no fields have been selected for mutation.
func (d RecordDraft) IsEmpty() bool {
	return !d.fieldID.IsSet() && !d.fieldBody.IsSet() && !d.fieldRaw.IsSet() && !d.fieldNote.IsSet() && !d.fieldEncoded.IsSet()
}

// Format omits pending draft values, including sensitive mutation inputs, from routine diagnostics.
func (RecordDraft) Format(state fmt.State, _ rune) { _, _ = state.Write([]byte("Record draft")) }

// RecordFieldChanges contains typed changes for persisted fields only.
type RecordFieldChanges struct {
	// ID retains the typed change for id.
	ID lifecycle.FieldChange[int]
	// Body retains the typed change for body.
	Body lifecycle.FieldChange[Payload]
	// Raw retains the typed change for raw.
	Raw lifecycle.FieldChange[[]byte]
	// Note retains the typed change for note.
	Note lifecycle.FieldChange[foundryvalue.Nullable[Payload]]
	// Encoded retains the typed change for encoded.
	Encoded lifecycle.FieldChange[string]
}

// RecordChanges contains immutable persisted snapshots and field changes. Relation loads and ignored fields are excluded.
type RecordChanges struct {
	before, after foundryvalue.Optional[Record]
	fields        RecordFieldChanges
	operation     foundryvalue.Optional[lifecycle.Operation]
}

// Operation identifies an automatically captured lifecycle write. Standalone Compare results have no operation.
func (c RecordChanges) Operation() foundryvalue.Optional[lifecycle.Operation] { return c.operation }

// Before returns the persisted model before the operation, or absence for creation.
func (c RecordChanges) Before() foundryvalue.Optional[Record] { return foundryRecordSnapshot(c.before) }

// After returns the persisted model after the operation, or absence for physical deletion. Soft deletion retains its stored result.
func (c RecordChanges) After() foundryvalue.Optional[Record] { return foundryRecordSnapshot(c.after) }

// Fields returns model-specific field changes by value.
func (c RecordChanges) Fields() RecordFieldChanges { return c.fields }

// Assigned reports whether any persisted field is assigned.
func (c RecordChanges) Assigned() bool {
	return c.fields.ID.Assigned() || c.fields.Body.Assigned() || c.fields.Raw.Assigned() || c.fields.Note.Assigned() || c.fields.Encoded.Assigned()
}

// Changed reports whether any persisted field is changed.
func (c RecordChanges) Changed() bool {
	return c.fields.ID.Changed() || c.fields.Body.Changed() || c.fields.Raw.Changed() || c.fields.Note.Changed() || c.fields.Encoded.Changed()
}

// String and GoString keep model snapshots out of routine diagnostics.
func (RecordChanges) String() string     { return "Record changes" }
func (c RecordChanges) GoString() string { return c.String() }

// CompareRecord is the generated lifecycle comparison boundary. Pass stored snapshots and the effective assignment draft; its values are not transformed or compared to the result. Both snapshots, when present, must have the same primary key. This function performs no database work or automatic capture.
func CompareRecord(before, after foundryvalue.Optional[Record], assigned RecordDraft) (RecordChanges, error) {
	before = foundryRecordSnapshot(before)
	after = foundryRecordSnapshot(after)
	var changes RecordChanges
	var err error
	changes.fields.ID, err = lifecycle.CompareModelField(codec.Signed[int](), before, after, assigned.fieldID.IsSet(), func(item Record) int { return item.ID })
	if err != nil {
		return RecordChanges{}, fmt.Errorf("compare Record.ID: %w", err)
	}
	if before.IsSet() && after.IsSet() && (changes.fields.ID.Changed() || changes.fields.ID.Assigned()) {
		return RecordChanges{}, foundryfault.New(foundryfault.Invalid, "model change cannot replace or assign its existing primary key")
	}
	changes.fields.Body, err = lifecycle.CompareModelField(codec.Bytes[Payload](), before, after, assigned.fieldBody.IsSet(), func(item Record) Payload { return item.Body })
	if err != nil {
		return RecordChanges{}, fmt.Errorf("compare Record.Body: %w", err)
	}
	changes.fields.Raw, err = lifecycle.CompareModelField(codec.Bytes[[]byte](), before, after, assigned.fieldRaw.IsSet(), func(item Record) []byte { return item.Raw })
	if err != nil {
		return RecordChanges{}, fmt.Errorf("compare Record.Raw: %w", err)
	}
	changes.fields.Note, err = lifecycle.CompareModelField(codec.Nullable(codec.Bytes[Payload]()), before, after, assigned.fieldNote.IsSet(), func(item Record) foundryvalue.Nullable[Payload] { return item.Note })
	if err != nil {
		return RecordChanges{}, fmt.Errorf("compare Record.Note: %w", err)
	}
	changes.fields.Encoded, err = lifecycle.CompareModelField(codec.String[string](), before, after, assigned.fieldEncoded.IsSet(), func(item Record) string { return item.Encoded })
	if err != nil {
		return RecordChanges{}, fmt.Errorf("compare Record.Encoded: %w", err)
	}
	changes.before = before
	changes.after = after
	return changes, nil
}
func foundryRecordSnapshot(snapshot foundryvalue.Optional[Record]) foundryvalue.Optional[Record] {
	item, present := snapshot.Get()
	if !present {
		return foundryvalue.Optional[Record]{}
	}
	return foundryvalue.Set(Record{
		ID:      item.ID,
		Body:    codec.Bytes[Payload]().Clone(item.Body),
		Raw:     codec.Bytes[[]byte]().Clone(item.Raw),
		Note:    codec.Nullable(codec.Bytes[Payload]()).Clone(item.Note),
		Encoded: item.Encoded,
	})
}

// RecordHooks declares typed normal-write callbacks. Reference a factory with hooks=Factory on the model directive. Callbacks run synchronously; do not retain draft or transaction pointers. Nil callbacks are skipped.
type RecordHooks struct {
	// Saving runs before Creating or Updating and may change assigned fields.
	Saving func(context.Context, *database.Tx, foundryvalue.Optional[Record], *RecordDraft) error
	// Creating runs before insert mutators; omitted required fields may be supplied here.
	Creating func(context.Context, *database.Tx, *RecordDraft) error
	// Updating receives the locked stored model before the write.
	Updating func(context.Context, *database.Tx, Record, *RecordDraft) error
	// Deleting receives the locked stored model before soft or physical deletion.
	Deleting func(context.Context, *database.Tx, Record) error
	// Restoring receives the locked stored model before its special lifecycle write.
	Restoring func(context.Context, *database.Tx, Record) error
	// ForceDeleting receives the locked stored model before its special lifecycle write.
	ForceDeleting func(context.Context, *database.Tx, Record) error
	// Created runs after SQL inside the transaction; returning an error rolls back the write.
	Created func(context.Context, *database.Tx, RecordChanges) error
	// Updated runs after SQL inside the transaction; returning an error rolls back the write.
	Updated func(context.Context, *database.Tx, RecordChanges) error
	// Deleted runs after SQL inside the transaction; returning an error rolls back the write.
	Deleted func(context.Context, *database.Tx, RecordChanges) error
	// Saved runs after SQL inside the transaction; returning an error rolls back the write.
	Saved func(context.Context, *database.Tx, RecordChanges) error
	// Restored runs after SQL inside the transaction; returning an error rolls back the write.
	Restored func(context.Context, *database.Tx, RecordChanges) error
	// ForceDeleted runs after SQL inside the transaction; returning an error rolls back the write.
	ForceDeleted func(context.Context, *database.Tx, RecordChanges) error
	// AfterCommit runs only after the outer transaction commits. Failures cannot roll back committed data; this callback is not crash durable.
	AfterCommit func(context.Context, lifecycle.Operation, RecordChanges) error
}

// RecordObserver retains this model's concrete hook factory type. Names are unique within the selected database.
type RecordObserver = lifecycle.Observer[Record, RecordHooks]

// NewRecordObserver declares a reusable typed observer identifier without registering or constructing hooks.
func NewRecordObserver(observer string) RecordObserver {
	return lifecycle.NewObserver[Record, RecordHooks](observer)
}

// RegisterRecordObserver binds dependency construction to a database module. Its returned factory runs once per normal write; reads and set-based writes skip it.
func RegisterRecordObserver(registrar *foundation.Registrar, pool foundation.Key[*database.DB], observer RecordObserver, construct func(foundation.Resolver) (func() RecordHooks, error)) error {
	return database.RegisterObserver(registrar, pool, observer, construct)
}
func (RecordHooks) foundryWriteHooks(ctx context.Context, observerSet lifecycle.Observers) (foundryquery.WriteHooks[Record], error) {
	factories, err := lifecycle.ObserverFactories[Record, RecordHooks](observerSet)
	if err != nil {
		return foundryquery.WriteHooks[Record]{}, err
	}
	var allHooks []RecordHooks
	if err := ctx.Err(); err != nil {
		return foundryquery.WriteHooks[Record]{}, err
	}
	for _, factory := range factories {
		if err := ctx.Err(); err != nil {
			return foundryquery.WriteHooks[Record]{}, err
		}
		allHooks = append(allHooks, factory())
	}
	if err := ctx.Err(); err != nil {
		return foundryquery.WriteHooks[Record]{}, err
	}
	return foundryquery.WriteHooks[Record]{
		Before: func(ctx context.Context, tx *database.Tx, operation lifecycle.Operation, before foundryvalue.Optional[Record], mutation foundryquery.Mutation[Record]) (foundryquery.Mutation[Record], error) {
			values, err := foundryquery.ReadMutation(mutation)
			if err != nil {
				return foundryquery.Mutation[Record]{}, err
			}
			var draft RecordDraft
			draft.fieldID, err = foundryquery.MutationValue[Record, int](values, "binary_records", "id")
			if err != nil {
				return foundryquery.Mutation[Record]{}, err
			}
			draft.fieldBody, err = foundryquery.MutationValue[Record, Input](values, "binary_records", "body")
			if err != nil {
				return foundryquery.Mutation[Record]{}, err
			}
			draft.fieldRaw, err = foundryquery.MutationValue[Record, []byte](values, "binary_records", "raw")
			if err != nil {
				return foundryquery.Mutation[Record]{}, err
			}
			draft.fieldNote, err = foundryquery.MutationValue[Record, foundryvalue.Nullable[Input]](values, "binary_records", "note")
			if err != nil {
				return foundryquery.Mutation[Record]{}, err
			}
			draft.fieldEncoded, err = foundryquery.MutationValue[Record, Input](values, "binary_records", "encoded")
			if err != nil {
				return foundryquery.Mutation[Record]{}, err
			}
			if err := ctx.Err(); err != nil {
				return foundryquery.Mutation[Record]{}, err
			}
			if operation == lifecycle.Create || operation == lifecycle.Update {
				for _, hooks := range allHooks {
					if hooks.Saving != nil {
						if err := hooks.Saving(ctx, tx, before, &draft); err != nil {
							return foundryquery.Mutation[Record]{}, err
						}
					}
					if err := ctx.Err(); err != nil {
						return foundryquery.Mutation[Record]{}, err
					}
				}
			}
			switch operation {
			case lifecycle.Create:
				for _, hooks := range allHooks {
					if hooks.Creating != nil {
						if err := hooks.Creating(ctx, tx, &draft); err != nil {
							return foundryquery.Mutation[Record]{}, err
						}
					}
					if err := ctx.Err(); err != nil {
						return foundryquery.Mutation[Record]{}, err
					}
				}
			case lifecycle.Update, lifecycle.Delete, lifecycle.SoftDelete, lifecycle.Restore, lifecycle.ForceDelete:
				current, present := before.Get()
				if !present {
					return foundryquery.Mutation[Record]{}, foundryfault.New(foundryfault.Invalid, "model hook requires a stored snapshot")
				}
				switch operation {
				case lifecycle.Update:
					for _, hooks := range allHooks {
						if hooks.Updating != nil {
							if err := hooks.Updating(ctx, tx, current, &draft); err != nil {
								return foundryquery.Mutation[Record]{}, err
							}
						}
						if err := ctx.Err(); err != nil {
							return foundryquery.Mutation[Record]{}, err
						}
					}
				case lifecycle.Delete, lifecycle.SoftDelete:
					for _, hooks := range allHooks {
						if hooks.Deleting != nil {
							if err := hooks.Deleting(ctx, tx, current); err != nil {
								return foundryquery.Mutation[Record]{}, err
							}
						}
						if err := ctx.Err(); err != nil {
							return foundryquery.Mutation[Record]{}, err
						}
					}
				case lifecycle.Restore:
					for _, hooks := range allHooks {
						if hooks.Restoring != nil {
							if err := hooks.Restoring(ctx, tx, current); err != nil {
								return foundryquery.Mutation[Record]{}, err
							}
						}
						if err := ctx.Err(); err != nil {
							return foundryquery.Mutation[Record]{}, err
						}
					}
				case lifecycle.ForceDelete:
					for _, hooks := range allHooks {
						if hooks.ForceDeleting != nil {
							if err := hooks.ForceDeleting(ctx, tx, current); err != nil {
								return foundryquery.Mutation[Record]{}, err
							}
						}
						if err := ctx.Err(); err != nil {
							return foundryquery.Mutation[Record]{}, err
						}
					}
					for _, hooks := range allHooks {
						if hooks.Deleting != nil {
							if err := hooks.Deleting(ctx, tx, current); err != nil {
								return foundryquery.Mutation[Record]{}, err
							}
						}
						if err := ctx.Err(); err != nil {
							return foundryquery.Mutation[Record]{}, err
						}
					}
				}
			default:
				return foundryquery.Mutation[Record]{}, foundryfault.New(foundryfault.Invalid, "invalid model hook operation")
			}
			return draft.foundryMutation(false)
		},
		After: func(ctx context.Context, tx *database.Tx, operation lifecycle.Operation, before, after foundryvalue.Optional[Record], mutation foundryquery.Mutation[Record]) error {
			values, err := foundryquery.ReadMutation(mutation)
			if err != nil {
				return err
			}
			var draft RecordDraft
			if values.Has("binary_records", "id") {
				var zero int
				draft.fieldID = foundryvalue.Set(zero)
			}
			if values.Has("binary_records", "body") {
				var zero Input
				draft.fieldBody = foundryvalue.Set(zero)
			}
			if values.Has("binary_records", "raw") {
				var zero []byte
				draft.fieldRaw = foundryvalue.Set(zero)
			}
			if values.Has("binary_records", "note") {
				var zero foundryvalue.Nullable[Input]
				draft.fieldNote = foundryvalue.Set(zero)
			}
			if values.Has("binary_records", "encoded") {
				var zero Input
				draft.fieldEncoded = foundryvalue.Set(zero)
			}
			changes, err := CompareRecord(before, after, draft)
			if err != nil {
				return err
			}
			changes.operation = foundryvalue.Set(operation)
			if err := ctx.Err(); err != nil {
				return err
			}
			switch operation {
			case lifecycle.Create:
				for _, hooks := range allHooks {
					if hooks.Created != nil {
						if err := hooks.Created(ctx, tx, changes); err != nil {
							return err
						}
					}
					if err := ctx.Err(); err != nil {
						return err
					}
				}
			case lifecycle.Update:
				for _, hooks := range allHooks {
					if hooks.Updated != nil {
						if err := hooks.Updated(ctx, tx, changes); err != nil {
							return err
						}
					}
					if err := ctx.Err(); err != nil {
						return err
					}
				}
			case lifecycle.Delete:
				for _, hooks := range allHooks {
					if hooks.Deleted != nil {
						if err := hooks.Deleted(ctx, tx, changes); err != nil {
							return err
						}
					}
					if err := ctx.Err(); err != nil {
						return err
					}
				}
			case lifecycle.SoftDelete:
				for _, hooks := range allHooks {
					if hooks.Deleted != nil {
						if err := hooks.Deleted(ctx, tx, changes); err != nil {
							return err
						}
					}
					if err := ctx.Err(); err != nil {
						return err
					}
				}
			case lifecycle.Restore:
				for _, hooks := range allHooks {
					if hooks.Restored != nil {
						if err := hooks.Restored(ctx, tx, changes); err != nil {
							return err
						}
					}
					if err := ctx.Err(); err != nil {
						return err
					}
				}
			case lifecycle.ForceDelete:
				for _, hooks := range allHooks {
					if hooks.Deleted != nil {
						if err := hooks.Deleted(ctx, tx, changes); err != nil {
							return err
						}
					}
					if err := ctx.Err(); err != nil {
						return err
					}
				}
				for _, hooks := range allHooks {
					if hooks.ForceDeleted != nil {
						if err := hooks.ForceDeleted(ctx, tx, changes); err != nil {
							return err
						}
					}
					if err := ctx.Err(); err != nil {
						return err
					}
				}
			default:
				return foundryfault.New(foundryfault.Invalid, "invalid model hook operation")
			}
			if operation == lifecycle.Create || operation == lifecycle.Update {
				for _, hooks := range allHooks {
					if hooks.Saved != nil {
						if err := hooks.Saved(ctx, tx, changes); err != nil {
							return err
						}
					}
					if err := ctx.Err(); err != nil {
						return err
					}
				}
			}
			for _, hooks := range allHooks {
				if hooks.AfterCommit != nil {
					if err := tx.AfterCommit(func(ctx context.Context) error { return hooks.AfterCommit(ctx, operation, changes) }); err != nil {
						return err
					}
				}
			}
			return nil
		}}, nil
}

// RecordRetrievalHooks declares complete-model read callbacks. Reference a local factory with retrieval=Factory on the model directive. The stored model is a read-only value; getters remain explicit.
type RecordRetrievalHooks struct {
	// Retrieved runs after successful stored hydration and row closure. The executor retains the caller's capability and wrappers; no write transaction is created implicitly. Return an error to stop this read. Nil is skipped.
	Retrieved func(context.Context, database.Executor, Record) error
}

// RecordRetrievalObserver retains this model's concrete retrieval factory type. Names share the selected database's write/retrieval namespace.
type RecordRetrievalObserver = lifecycle.Observer[Record, RecordRetrievalHooks]

// NewRecordRetrievalObserver declares a typed retrieval observer without registering or constructing hooks.
func NewRecordRetrievalObserver(observer string) RecordRetrievalObserver {
	return lifecycle.NewRetrievalObserver[Record, RecordRetrievalHooks](observer)
}

// RegisterRecordRetrievalObserver binds dependency construction to a database module. Its factory runs once per nonempty complete fetch/batch and selected model role; write hydration, DTOs and scalar reads skip it.
func RegisterRecordRetrievalObserver(registrar *foundation.Registrar, pool foundation.Key[*database.DB], observer RecordRetrievalObserver, construct func(foundation.Resolver) (func() RecordRetrievalHooks, error)) error {
	return database.RegisterObserver(registrar, pool, observer, construct)
}
func (RecordRetrievalHooks) foundryRetrievalHooks(ctx context.Context, observerSet lifecycle.Observers) (foundryquery.RetrievalHooks[Record], error) {
	factories, err := lifecycle.RetrievalObserverFactories[Record, RecordRetrievalHooks](observerSet)
	if err != nil {
		return foundryquery.RetrievalHooks[Record]{}, err
	}
	var allHooks []RecordRetrievalHooks
	if err := ctx.Err(); err != nil {
		return foundryquery.RetrievalHooks[Record]{}, err
	}
	for _, factory := range factories {
		if err := ctx.Err(); err != nil {
			return foundryquery.RetrievalHooks[Record]{}, err
		}
		allHooks = append(allHooks, factory())
	}
	if err := ctx.Err(); err != nil {
		return foundryquery.RetrievalHooks[Record]{}, err
	}
	return foundryquery.RetrievalHooks[Record]{Retrieved: func(ctx context.Context, executor database.Executor, item Record) error {
		for _, hooks := range allHooks {
			if err := ctx.Err(); err != nil {
				return err
			}
			if hooks.Retrieved != nil {
				if err := hooks.Retrieved(ctx, executor, item); err != nil {
					return err
				}
			}
		}
		return ctx.Err()
	}}, nil
}

// RecordAuditPolicy selects stored fields for auditing. Zero applies automatic sensitive-name redaction.
// Exclusion/redaction cannot hide the primary key while retaining it as the subject identity; that policy fails capture.
type RecordAuditPolicy struct {
	_ [0]*Record
	// ID controls the audit representation of stored binary_records.id.
	ID record.Disclosure
	// Body controls the audit representation of stored binary_records.body.
	Body record.Disclosure
	// Raw controls the audit representation of stored binary_records.raw.
	Raw record.Disclosure
	// Note controls the audit representation of stored binary_records.note.
	Note record.Disclosure
	// Encoded controls the audit representation of stored binary_records.encoded.
	Encoded record.Disclosure
}

// Audit captures this operation's existing stored changes without getters, mutators or additional database work.
// Standalone Compare results have no captured operation and cannot become lifecycle audit records.
func (changes RecordChanges) Audit(policy RecordAuditPolicy) (record.Model[Record, int], error) {
	operation, present := changes.operation.Get()
	if !present {
		return record.Model[Record, int]{}, foundryfault.New(foundryfault.Missing, "audit requires captured model changes")
	}
	item, present := changes.after.Get()
	if !present {
		item, present = changes.before.Get()
	}
	if !present {
		return record.Model[Record, int]{}, foundryfault.New(foundryfault.Missing, "audit requires a stored model snapshot")
	}
	builder, err := record.NewBuilder(item.FoundryReference(), operation, "id", policy.ID)
	if err != nil {
		return record.Model[Record, int]{}, err
	}
	var captured record.Field[Record]
	captured, err = record.CaptureField[Record]("id", codec.Signed[int](), changes.fields.ID, policy.ID)
	if err != nil {
		return record.Model[Record, int]{}, err
	}
	if err = builder.Add(captured); err != nil {
		return record.Model[Record, int]{}, err
	}
	captured, err = record.CaptureField[Record]("body", codec.Bytes[Payload](), changes.fields.Body, policy.Body)
	if err != nil {
		return record.Model[Record, int]{}, err
	}
	if err = builder.Add(captured); err != nil {
		return record.Model[Record, int]{}, err
	}
	captured, err = record.CaptureField[Record]("raw", codec.Bytes[[]byte](), changes.fields.Raw, policy.Raw)
	if err != nil {
		return record.Model[Record, int]{}, err
	}
	if err = builder.Add(captured); err != nil {
		return record.Model[Record, int]{}, err
	}
	captured, err = record.CaptureField[Record]("note", codec.Nullable(codec.Bytes[Payload]()), changes.fields.Note, policy.Note)
	if err != nil {
		return record.Model[Record, int]{}, err
	}
	if err = builder.Add(captured); err != nil {
		return record.Model[Record, int]{}, err
	}
	captured, err = record.CaptureField[Record]("encoded", codec.String[string](), changes.fields.Encoded, policy.Encoded)
	if err != nil {
		return record.Model[Record, int]{}, err
	}
	if err = builder.Add(captured); err != nil {
		return record.Model[Record, int]{}, err
	}
	return builder.Build()
}

// RecordAuditFieldSet contains typed historical fields. An omitted field differs from an absent model or SQL NULL.
type RecordAuditFieldSet struct {
	_ [0]*Record
	// ID retains stored binary_records.id after write mutators; read accessors do not replace audit values.
	ID foundryvalue.Optional[record.FieldChange[int]]
	// Body retains stored binary_records.body after write mutators; read accessors do not replace audit values.
	// Binary persistence uses bytea and owns byte buffers in drafts, query values and change snapshots. A non-nil empty slice is present; nil is invalid. Use Nullable and the generated Clear setter for SQL NULL. Binary fields cannot be identity or relation keys.
	// Record.Body retains stored binary_records.body. Custom setter: [Record.MutateBody] transforms assigned values during persistence through [RecordDraft.SetBody]. Direct field assignment and draft construction do not invoke it.
	// The custom setter accepts binarymodels.Input and produces stored binarymodels.Payload; pass fresh input to the draft/conflict setter and use stored values for query comparisons.
	Body foundryvalue.Optional[record.FieldChange[Payload]]
	// Raw retains stored binary_records.raw after write mutators; read accessors do not replace audit values.
	// Binary persistence uses bytea and owns byte buffers in drafts, query values and change snapshots. A non-nil empty slice is present; nil is invalid. Use Nullable and the generated Clear setter for SQL NULL. Binary fields cannot be identity or relation keys.
	Raw foundryvalue.Optional[record.FieldChange[[]byte]]
	// Note retains stored binary_records.note after write mutators; read accessors do not replace audit values.
	// Binary persistence uses bytea and owns byte buffers in drafts, query values and change snapshots. A non-nil empty slice is present; nil is invalid. Use Nullable and the generated Clear setter for SQL NULL. Binary fields cannot be identity or relation keys.
	// Record.Note retains stored binary_records.note. Custom setter: [Record.MutateNote] transforms assigned values during persistence through [RecordDraft.SetNote]. Direct field assignment and draft construction do not invoke it.
	// The custom setter accepts binarymodels.Input and produces stored binarymodels.Payload; pass fresh input to the draft/conflict setter and use stored values for query comparisons.
	// The write mutator skips omitted values and explicit SQL NULL; an assigned scalar zero value still invokes it.
	Note foundryvalue.Optional[record.FieldChange[foundryvalue.Nullable[Payload]]]
	// Encoded retains stored binary_records.encoded after write mutators; read accessors do not replace audit values.
	// Record.Encoded retains stored binary_records.encoded. Custom setter: [Record.MutateEncoded] transforms assigned values during persistence through [RecordDraft.SetEncoded]. Direct field assignment and draft construction do not invoke it.
	// The custom setter accepts binarymodels.Input and produces stored string; pass fresh input to the draft/conflict setter and use stored values for query comparisons.
	Encoded foundryvalue.Optional[record.FieldChange[string]]
}

// RecordAuditFields reads model-owned history through its declared codecs, without populating a partial model.
// Get on a redacted field reports an explicit error; its Snapshot remains available for deliberate audit export.
func RecordAuditFields(history record.Model[Record, int]) (RecordAuditFieldSet, error) {
	view, err := record.Inspect(history)
	if err != nil {
		return RecordAuditFieldSet{}, err
	}
	var fields RecordAuditFieldSet
	fields.ID, err = record.ReadField(view, "id", codec.Signed[int]())
	if err != nil {
		return RecordAuditFieldSet{}, err
	}
	fields.Body, err = record.ReadField(view, "body", codec.Bytes[Payload]())
	if err != nil {
		return RecordAuditFieldSet{}, err
	}
	fields.Raw, err = record.ReadField(view, "raw", codec.Bytes[[]byte]())
	if err != nil {
		return RecordAuditFieldSet{}, err
	}
	fields.Note, err = record.ReadField(view, "note", codec.Nullable(codec.Bytes[Payload]()))
	if err != nil {
		return RecordAuditFieldSet{}, err
	}
	fields.Encoded, err = record.ReadField(view, "encoded", codec.String[string]())
	if err != nil {
		return RecordAuditFieldSet{}, err
	}
	return fields, nil
}

// RecordAuditing declares automatic auditing for normal lifecycle writes. Register it once through audit.Register.
// Existing observer registration owns dependency construction, duplicate detection and transaction lifetime.
func RecordAuditing(policy RecordAuditPolicy) record.Declaration {
	return record.Declare(func(registrar *foundation.Registrar, pool foundation.Key[*database.DB], resolve record.ResolveWriter) error {
		name, err := record.ObserverName[Record]()
		if err != nil {
			return err
		}
		return RegisterRecordObserver(registrar, pool, NewRecordObserver(name), func(resolver foundation.Resolver) (func() RecordHooks, error) {
			writer, err := resolve(resolver)
			if err != nil {
				return nil, err
			}
			if writer == nil {
				return nil, foundryfault.New(foundryfault.Invalid, "audit writer is not initialized")
			}
			return func() RecordHooks {
				write := func(ctx context.Context, tx *database.Tx, changes RecordChanges) error {
					captured, err := changes.Audit(policy)
					if err != nil {
						return err
					}
					return writer.RecordModel(ctx, tx, captured.Entry())
				}
				return RecordHooks{Created: write, Updated: write, Deleted: write, Restored: write}
			}, nil
		})
	})
}
